    "description": "日本央行行长植田和男称，货币政策思路没有大变化。我们迄今已累计五次上调政策利率，因此我们需要仔细审视累计影响将对经济产生何种作用。货币条件仍然宽松，因此我们希望继续加息。将在考虑物价上行风险的情况下讨论货币政策。希望在下次会议上讨论经济情景实现的可能性是否提高，以及通胀风险是否加大。（新浪财经）",
    "content": "日本央行行长植田和男称，货币政策思路没有大变化。我们迄今已累计五次上调政策利率，因此我们需要仔细审视累计影响将对经济产生何种作用。货币条件仍然宽松，因此我们希望继续加息。将在考虑物价上行风险的情况下讨论货币政策。希望在下次会议上讨论经济情景实现的可能性是否提高，以及通胀风险是否加大。（新浪财经）"
