    "pub_date": "2026-09-02 08:27:37",
    "author": "",
    "description": "《国家基本药物目录(2026版)》自昨天起正式施行。基本药物是指满足疾病防治基本用药需求，剂型适宜，价格合理，能够保障供应，可公平获得的药品。群众看病、医生开药，临床用药优先用什么，国家基本药物目录是重要依据。新版目录药物总数增至794种，新增116个品种药物。此次目录更新调整主要聚焦于哪些药物？回应了哪些群众关切的用药需求？一起了解。",
    "content": "《国家基本药物目录(2026版)》自昨天起正式施行。基本药物是指满足疾病防治基本用药需求，剂型适宜，价格合理，能够保障供应，可公平获得的药品。群众看病、医生开药，临床用药优先用什么，国家基本药物目录是重要依据。新版目录药物总数增至794种，新增116个品种药物。此次目录更新调整主要聚焦于哪些药物？回应了哪些群众关切的用药需求？一起了解。"
