    "content": "2026年09月02日 上海合作组织（以下简称“上合组织”）成员国， 基于历史纽带、百年睦邻传统与相互尊重， 声明恪守《上合组织宪章》《联合国宪章》及公认国际法原则和准则，包括尊重主权、领土完整、不干涉内政等， 秉持“互信、互利、平等、协商、尊重多样文明、谋求共同发展”的“上海精神”， 确认核安保的责任完全由该国承担，指出核安全的责任由核设施运营机构及核设施所在国承担， 高度重视核安全与核安保问题，这是直接影响上合组织成员国人民生活的重要国际安全要素， 对核材料及其他放射性物质非法贩运、针对核设施和基础设施（包括计…"
