    "description": "2026年09月02日 本报记者 张武军摄 \"> 本报吉隆9月1日电 （记者卞民德、刘温馨、徐驭尧）历经连续多日昼夜奋战，216国道通往吉隆口岸国门的最后一段路预计2日上午抢通。多方救援力量正集结待命，大规模搜救工作即将全面展开。 灾害发生以来，各方救援力量“水陆空”三路并进。但因通往吉隆口岸的216国道部分路段损毁，大规模救援工作受限。救援人员一度只能携带轻型装备通过索降、直升机投送救援人员等方式突进，救援车辆、大型机械、重装备等难以…",
    "content": "2026年09月02日 9月1日，中国安能救援力量在距离吉隆口岸700米位置的216国道抢修道路。 本报记者 张武军摄 \"> 本报吉隆9月1日电&nbsp;&nbsp;（记者卞民德、刘温馨、徐驭尧）历经连续多日昼夜奋战，216国道通往吉隆口岸国门的最后一段路预计2日上午抢通。多方救援力量正集结待命，大规模搜救工作即将全面展开。 灾害发生以来，各方救援力量“水陆空”三路并进。但因通往吉隆口岸的216国道部分路段损毁，大规模救援工作受限。救援人员一度只能携带轻型装备通过索降、直升机投送救援人员等方式突进，救援车辆、大型…"
