    "description": "2026年09月02日 9月1日 晴 中午采访完从外地赶来支援的心理医生，我又去了趟位于吉隆镇吉普村的安置点。泥石流灾害发生的前一天，我到过这里，当时游客不少，如今冷清了许多。 在村口，村民达娃看见我，从锅里捞出一根冒着热气的玉米递过来，“我们这儿的玉米香，坐下吃。” “这两天，我儿子尼玛多吉开着大卡车，帮救援人员运输石料。”达娃和我聊起了家常，言语中透着自豪，“他是退伍军人，一接到前方需要支援的消息就过去了。每天一大早出门，夜里很晚才…",
    "content": "2026年09月02日 9月1日&nbsp;&nbsp;晴 中午采访完从外地赶来支援的心理医生，我又去了趟位于吉隆镇吉普村的安置点。泥石流灾害发生的前一天，我到过这里，当时游客不少，如今冷清了许多。 在村口，村民达娃看见我，从锅里捞出一根冒着热气的玉米递过来，“我们这儿的玉米香，坐下吃。” “这两天，我儿子尼玛多吉开着大卡车，帮救援人员运输石料。”达娃和我聊起了家常，言语中透着自豪，“他是退伍军人，一接到前方需要支援的消息就过去了。每天一大早出门，夜里很晚才回来。” 达娃说，尼玛多吉和大家讲过前方的情况，“他说那儿…"
