    "content": "2026年09月02日 吉隆口岸附近地形复杂、天气多变，无人机在抢险救援一线发挥了重要作用。 26日16时许，西藏林芝一家智能科技公司的00后无人机飞手孙靖收到了“吉隆救灾一线需要设备支持”的消息，立即和几名同伴带着设备，星夜兼程，于次日下午抵达吉隆救灾一线，作为志愿者加入救援队伍。 “第一批徒步翻山的消防员到达口岸区域后，急需补给和睡袋。我们团队连夜用无人机向口岸方向运送物资，为一线救援人员提供保障。”孙靖说。 在这次救援中，孙靖使用的运载无人机最大承载量是200公斤。“有一次，消防员需要从河这边到对岸去打锚点，…"
