    "description": "2026年09月02日 本报南宁9月1日电 （记者张云河）8月31日，平陆运河首艘指挥管理船“平陆001”正式交付使用。该船集航道巡查、通航调度、水上应急指挥等功能于一体，是运河上第一艘正式入列的指挥管理船。 “平陆001”为智能指挥船，已入级中国船级社（CCS），可安全航行于沿海航区及平陆运河内河A级、B级水域。全船核定船员7人，可搭载作业人员50人。 目前，“平陆001”已顺利抵达钦州水上综合服务区。下一步，“平陆001”的智慧航行…",
    "content": "2026年09月02日 本报南宁9月1日电&nbsp;&nbsp;（记者张云河）8月31日，平陆运河首艘指挥管理船“平陆001”正式交付使用。该船集航道巡查、通航调度、水上应急指挥等功能于一体，是运河上第一艘正式入列的指挥管理船。 “平陆001”为智能指挥船，已入级中国船级社（CCS），可安全航行于沿海航区及平陆运河内河A级、B级水域。全船核定船员7人，可搭载作业人员50人。 目前，“平陆001”已顺利抵达钦州水上综合服务区。下一步，“平陆001”的智慧航行系统将与运河岸基设施展开全面联调联试，实现数据融合、远程感…"
