    "content": "2026年09月02日 8月30日，由人民日报社主办的中国—埃及媒体高质量共建“一带一路”联合采访成果分享会在埃及首都开罗举行。分享会上，两国媒体人士、专家学者等结合联合采访成果，就加强媒体交流合作、共同讲好中埃高质量共建“一带一路”故事展开对话交流。 8月23日至27日，来自人民日报和11家埃及主流媒体的记者，同埃及专家学者、网红博主等近30人走访埃及多地，深入中埃合作项目现场开展联合采访。 “两国记者开展联合采访，从不同视角讲述埃中合作的生动故事，实现了从传统单向新闻报道向共同创作的转变，意义深远。”曾担任驻华…"
