    "author": "",
    "description": "2026年09月02日 对话人： 孟繁哲 本报评论员 姜照雯 四川日报评论员 孟繁哲：科技创新是推动高质量发展的引擎。四川绵阳坐拥20家国家级科研院所，科研资源之丰沛在西部少有，却曾面临“科技强、产业弱”的困境。如今，研发投入强度稳居全国前列，培育国省级产业集群24个，“十四五”时期末高技术制造业增加值占比提升至37.6%。绵阳的创新蝶变源于做对了什么？ 姜照雯：实验室到生产线，中间隔着技术验证、中试放大、市场对接等多个环节，单靠任何一…",
    "content": "2026年09月02日 对话人： 孟繁哲&nbsp;&nbsp;本报评论员 姜照雯&nbsp;&nbsp;四川日报评论员 孟繁哲：科技创新是推动高质量发展的引擎。四川绵阳坐拥20家国家级科研院所，科研资源之丰沛在西部少有，却曾面临“科技强、产业弱”的困境。如今，研发投入强度稳居全国前列，培育国省级产业集群24个，“十四五”时期末高技术制造业增加值占比提升至37.6%。绵阳的创新蝶变源于做对了什么？ 姜照雯：实验室到生产线，中间隔着技术验证、中试放大、市场对接等多个环节，单靠任何一方都难以独自跨越。 当好“创新组织者…"
