    "description": "2026年09月02日 新华社记者 徐 昱摄 \"> 本报北京9月1日电 （记者王云杉）记者从国家能源局获悉：截至今年7月底，我国光伏发电装机容量达到12.86亿千瓦，其中集中式光伏7.04亿千瓦、分布式光伏5.82亿千瓦。光伏发电的装机容量首次超过煤电（煤电装机容量为12.85亿千瓦），成为我国装机规模最大的电源品类。 今年7月，光伏发电新增装机容量1373万千瓦，同比增长43%。今年前7月，光伏发电量达到8024亿千瓦时，同比提升15…",
