    "description": "2026年09月02日 本报兰州9月1日电 （记者宋朝军）9月1日，甘肃省公共数据资源登记平台、授权运营平台正式上线运行。甘肃省公共数据迈入规范化登记、标准化管理、市场化运营、全流程监管的新阶段，为激活数据要素价值、赋能数字经济高质量发展筑牢基础底座。 甘肃省公共数据资源登记平台是全省公共数据资源统一登记入口和管理载体，提供登记申请、审核公示、资源查询、存证管理、统计分析等全流程数字化服务。平台已与国家公共数据资源登记平台实现互联互通，…",
    "content": "2026年09月02日 本报兰州9月1日电&nbsp;&nbsp;（记者宋朝军）9月1日，甘肃省公共数据资源登记平台、授权运营平台正式上线运行。甘肃省公共数据迈入规范化登记、标准化管理、市场化运营、全流程监管的新阶段，为激活数据要素价值、赋能数字经济高质量发展筑牢基础底座。 甘肃省公共数据资源登记平台是全省公共数据资源统一登记入口和管理载体，提供登记申请、审核公示、资源查询、存证管理、统计分析等全流程数字化服务。平台已与国家公共数据资源登记平台实现互联互通，推动甘肃省公共数据资源统一登记、规范管理和高效利用。甘肃省…"
