    "description": "2026年09月02日 换乘四通八达的地铁抵达目的地，坐上定制快巴从城郊直达市区商圈，在城市绿道扫码骑一辆共享单车……2025年，我国每天超2亿人次选择绿色方式出行，城市绿色出行量位居全球第一。绿色出行，已经成为越来越多人的主动选择，融入人们的日常生活。 相关设施不断完善，助力绿色出行发展。基础设施的硬支撑够“扎实”，广东深圳轨道与公交一次换乘已覆盖全市建成区，打通市民出行“最后一公里”；出行服务的软配套够“聪明”，四川成都公交依托“智…",
    "content": "2026年09月02日 换乘四通八达的地铁抵达目的地，坐上定制快巴从城郊直达市区商圈，在城市绿道扫码骑一辆共享单车……2025年，我国每天超2亿人次选择绿色方式出行，城市绿色出行量位居全球第一。绿色出行，已经成为越来越多人的主动选择，融入人们的日常生活。 相关设施不断完善，助力绿色出行发展。基础设施的硬支撑够“扎实”，广东深圳轨道与公交一次换乘已覆盖全市建成区，打通市民出行“最后一公里”；出行服务的软配套够“聪明”，四川成都公交依托“智慧公交大脑”调度系统，实现“一屏总览、一键掌握、一体联动”，让公众出行更方便快捷…"
