    "description": "2026年09月02日 本报北京9月1日电 （记者王浩）记者从水利部获悉：截至9月1日，大藤峡水利枢纽累计发电量突破300亿千瓦时大关，连续安全运行超2300天。 据测算，300亿千瓦时绿色电能可满足一座200万人口城市近两年的用电需求，支撑约4250亿元GDP增长，相当于节约标准煤约990万吨、减排二氧化碳约2475万吨。 大藤峡工程是国家水网重要结点和珠江流域控制性工程，集防洪、航运、发电、补水压咸和灌溉等综合效益于一体。电站共布置…",
    "content": "2026年09月02日 本报北京9月1日电&nbsp;&nbsp;（记者王浩）记者从水利部获悉：截至9月1日，大藤峡水利枢纽累计发电量突破300亿千瓦时大关，连续安全运行超2300天。 据测算，300亿千瓦时绿色电能可满足一座200万人口城市近两年的用电需求，支撑约4250亿元GDP增长，相当于节约标准煤约990万吨、减排二氧化碳约2475万吨。 大藤峡工程是国家水网重要结点和珠江流域控制性工程，集防洪、航运、发电、补水压咸和灌溉等综合效益于一体。电站共布置8台国内最大的轴流转桨式水轮发电机组，总装机容量160万千…"
