    "description": "2026年09月02日 本报北京9月1日电 （记者蒋雪鸿、邓剑洋）今年第18号台风“沙德尔”于8月28日在浙江登陆后，在8月30日减弱停编，其残余涡旋移入南海后于9月1日凌晨再度加强为台风（热带风暴级），中央气象台继续维持原台风名称“沙德尔”和编号2618不变。当前“沙德尔”处于大型季风槽中，与台湾以东热带扰动等多系统共存，江南、华南等地需防范持续强降雨及次生灾害。 9月1日18时，中央气象台发布渍涝风险气象预报、继续发布暴雨黄色预警和…",
    "content": "2026年09月02日 本报北京9月1日电&nbsp;&nbsp;（记者蒋雪鸿、邓剑洋）今年第18号台风“沙德尔”于8月28日在浙江登陆后，在8月30日减弱停编，其残余涡旋移入南海后于9月1日凌晨再度加强为台风（热带风暴级），中央气象台继续维持原台风名称“沙德尔”和编号2618不变。当前“沙德尔”处于大型季风槽中，与台湾以东热带扰动等多系统共存，江南、华南等地需防范持续强降雨及次生灾害。 9月1日18时，中央气象台发布渍涝风险气象预报、继续发布暴雨黄色预警和台风蓝色预警；水利部和中国气象局联合发布橙色山洪灾害气象预…"
