    "description": "2026年09月02日 国家统计局发布的7月份国民经济运行数据中，一项指标颇为亮眼：前7个月，新动能对规模以上工业增长的贡献率为50.9%，比上半年提高3个百分点。新动能首次扛起“半壁江山”，充分反映了我国经济向新向优的积极态势。 分析内外部形势，更能体会这“50.9%”的分量。向外看，全球产业竞争日趋激烈，贸易保护主义持续抬头；向内看，国内供强需弱矛盾仍然较为突出，部分传统行业转型压力较大。内外环境承压之下，新动能对于经济发展、工业增…",
