    "description": "2026年09月02日 在北京从事新媒体工作的80后王楠在下班回家的地铁上，点开了同事分享的链接——金枕榴莲，泰国直采，价格实惠，包邮到家。她下了单，3天后，一个沉甸甸的榴莲就送到了家门口。 这个动作再平常不过。 近期，海关总署公布了一组数据：今年上半年，跨境电商出口海外仓规模同比增长3.3倍，全国已有1.4亿人借助跨境电商选购全球商品。 王楠可能并未意识到，自己也是这1.4亿分之一。她只感觉世界正在“变小”——从泰国榴莲到法国小众香氛…",
    "content": "2026年09月02日 在北京从事新媒体工作的80后王楠在下班回家的地铁上，点开了同事分享的链接——金枕榴莲，泰国直采，价格实惠，包邮到家。她下了单，3天后，一个沉甸甸的榴莲就送到了家门口。 这个动作再平常不过。 近期，海关总署公布了一组数据：今年上半年，跨境电商出口海外仓规模同比增长3.3倍，全国已有1.4亿人借助跨境电商选购全球商品。 王楠可能并未意识到，自己也是这1.4亿分之一。她只感觉世界正在“变小”——从泰国榴莲到法国小众香氛，从澳大利亚保健品到德国厨具，那些曾经需要托人代购、需要出境才能买到的商品，如今…"
