    "description": "2026年09月02日 浙江衢州城北，有个叫黄蒙的小村子，藏在千里岗山脉深处。这里，山峦层叠如屏，满眼苍翠欲滴，一条清溪潺潺流过，两岸屋舍错落。 进村，就能看到“江文焕故居”的指示牌。沿石阶而上，一座鹅卵石砌的老屋安然矗立。推门而入，木床、桌子、衣柜还是当年的模样。 老屋旁边，是一个陈列馆。馆中，不仅陈列着江文焕烈士的生平事迹，还有他写给妻子程正迦的一封封家书。泛黄的纸页，承载着他真切深沉的内心感悟：“志向不是自己生成的，而是靠外界的压…",
    "content": "2026年09月02日 浙江衢州城北，有个叫黄蒙的小村子，藏在千里岗山脉深处。这里，山峦层叠如屏，满眼苍翠欲滴，一条清溪潺潺流过，两岸屋舍错落。 进村，就能看到“江文焕故居”的指示牌。沿石阶而上，一座鹅卵石砌的老屋安然矗立。推门而入，木床、桌子、衣柜还是当年的模样。 老屋旁边，是一个陈列馆。馆中，不仅陈列着江文焕烈士的生平事迹，还有他写给妻子程正迦的一封封家书。泛黄的纸页，承载着他真切深沉的内心感悟：“志向不是自己生成的，而是靠外界的压迫和引导而成功的，所以如果我们能够善于利用我们的困苦，不但是不可对困苦加以诅咒，…"
