    "title": "华昌化工：控股股东将变更为苏州宣力，明起复牌",
    "link": "https://36kr.com/newsflashes/3965512623152641?f=rss",
    "pub_date": "2026-09-02 08:17:59",
    "author": "",
    "description": "36氪获悉，华昌化工公告，公司股票自2026年9月2日上午开市起复牌。控股股东华纳投资拟以6.18元/股向苏州宣力协议转让2.29亿股股份（占总股本24%），转让价款总额14.13亿元。交易完成后，控股股东将变更为苏州宣力，实际控制人变更为程仁杰。",
    "content": "36氪获悉，华昌化工公告，公司股票自2026年9月2日上午开市起复牌。控股股东华纳投资拟以6.18元/股向苏州宣力协议转让2.29亿股股份（占总股本24%），转让价款总额14.13亿元。交易完成后，控股股东将变更为苏州宣力，实际控制人变更为程仁杰。"
