    "author": "",
    "description": "“我觉得我们现在生活的这个时代，是不是真的有点访谈过剩了？ “鲁豫访谈别人，别人访谈鲁豫；papi酱访谈别人，别人访谈papi酱。每个人都有自己的节目，每个人也都在成为别人的嘉宾，好像每个人在这个时代都拥有一个值得被展开的人生方法论。 “每个人的生活都必须得提炼出来几句能够被广泛流传的答案，这是我最近看所有访谈最大的感触。我们真的需要那么多访谈吗？” 8月21日，互联网博主“壮壮鲨”发布视频，“说真的，我不反感访谈，我只是觉得我们正在进…",
    "content": "“我觉得我们现在生活的这个时代，是不是真的有点访谈过剩了？ “鲁豫访谈别人，别人访谈鲁豫；papi酱访谈别人，别人访谈papi酱。每个人都有自己的节目，每个人也都在成为别人的嘉宾，好像每个人在这个时代都拥有一个值得被展开的人生方法论。 “每个人的生活都必须得提炼出来几句能够被广泛流传的答案，这是我最近看所有访谈最大的感触。我们真的需要那么多访谈吗？” 8月21日，互联网博主“壮壮鲨”发布视频，“说真的，我不反感访谈，我只是觉得我们正在进入一个意义过剩的时代。” 一位网友在“壮壮鲨”的视频下留言：“我今年三月份很喜欢…"
