    "author": "程乐松",
    "description": "一般而言，读者在一本书中最先读到的序言是作者写作时最后完成的。这种独特的衔尾蛇模式是因为作者在完成写作之后，他自己成了第一个读者。诠释学总是要建立一个作者、读者与文本之间的三角关系，而作者完成文本之后，文本就有了其自身的独立性，等待着包括作者在内的所有读者理解和诠释其内涵。因此，作者的角色就转变为读者的“导游”，将自己的书写和阅读体验写成一个导览图，让读者在理解自己的写作意图和风格的基础上，避免在阅读的时候“踩坑”。这是作者与读者之间就…",
