    "description": "《上海粮食计划供应制度研究（1953-1993）》 田锡全等著，上海人民出版社 随着1953年粮食统购统销政策的出台和具体实施，计划供应制度开始在粮食消费领域逐渐确立起来。本书以上海为个案，集中探讨了粮食计划供应制度的构建与演进过程、该制度在城市社会的运作状况及其所引起的广泛社会变动。全书以时间为线索，探讨了粮食计划供应制度的缘起以及上海粮食计划供应制度（包括粮食票证制度）的创建及其演进脉络；考察了宣传动员与上海粮食计划供应制度建立之间…",
