    "content": "8月29日，华东师范大学教授李明洁做客行知读书会，以纽约曼哈顿街头巷尾的酒店、酒吧、饭店墙壁为线索，为现场读者展开了一幅关于城市记忆、资本与文化的长卷。她从纽约数万家餐饮空间中选取了四家具有代表性的场所，逐一推开它们的门，带领听众“听见”墙壁上那些沉默的“画外音”。 李明洁解释，之所以将研究视角锁定餐厅、酒吧、酒馆等餐饮空间，核心在于其极致的公共性与包容性。 李明洁现场分享 “餐饮空间是所有市民都能自由进入、平等停留的场域，个体的私人休憩行为，会在这个开放场景中转化为公共交流，完美契合哈贝马斯提出的公共领域概念。”…"
