    "author": "",
    "description": "开学第一天不仅要让孩子们学得好，也要吃得好。上午10点45分，在工作人员的带领下，记者走进北京市海淀区第二十中学附属实验学校的后厨，一进门烟火气扑面而来。操作台上各类菜品被摆放得整整齐齐，铁锅翻炒滋滋作响，师傅们正忙着烹制孩子们中午的午餐，土豆炖牛肉、素什锦轮番出锅，热气裹挟着饭菜香气在后厨弥漫。一旁的万能蒸烤箱精准控制油盐用量和烹饪时间，再也不靠老师傅凭手感拿捏咸淡。",
