    "description": "高光谱成像能通过物质特有的光谱信息识别材质和成分，是遥感监测、工业检测等领域的重要技术。近日，北京理工大学科研团队首创片上光谱计算新方法，将原本依赖大型服务器完成的光谱解析集成到便携设备中，实现高光谱信息的现场实时处理。相关成果近日发表于国际学术期刊《科学》。",
