    "content": "近日，国家动物博物馆里发生令人愤慨的一幕： 一层濒危动物展厅里，两个孩子在舟山眼镜蛇标本和莽山原矛头蝮标本前玩闹，不断用手抓、用脚踢标本。随行的父亲没有制止，反而把两件标本拿起来，递给孩子，跟着一起玩闹。其间，莽山原矛头蝮标本受损。 事后，国家动物博物馆对此行为表示强烈谴责。 9月1日，澎湃新闻联系上莽山原矛头蝮标本的捐赠者——莽山国家级自然保护区自然博物馆原馆长陈远辉。这位77岁的老人正是莽山原矛头蝮的发现者。他告诉澎湃新闻，得知蛇标本受损的消息后深感心痛。他表示，蛇类标本质地脆弱，如此珍贵的物种资料，今后应当用…"
