    "pub_date": "2026-09-02 07:22:01",
    "author": "",
    "description": "近日，一件发生在国家动物博物馆的不文明参观事件引发广泛关注。8月29日晚，国家动物博物馆发布《强烈谴责！》文章提到，在一层濒危动物展厅两个孩子在舟山眼镜蛇标本和莽山原矛头蝮标本前玩闹，不断用手抓、用脚踢标本。随行的父亲非但没有制止，反而把两件标本拿起来，递给孩子。两件真品标本不同程度受损，其中莽山原矛头蝮标本伤情较重。",
