    "content": "新华社联合国9月1日电 中国常驻联合国副代表孙磊1日在联大审议乌克兰问题时发言，敦促早日实现危机的政治解决。 孙磊说，乌克兰问题仍在延宕。自联大上次讨论乌克兰问题以来，地面形势非但没有得到缓和反而愈演愈烈，袭击和平民伤亡事件频繁发生，战事还对第三方国家造成严重负面影响，令人深感忧虑和痛心。中方呼吁当事方和国际社会共同努力，推动早日实现停火止战、危机政治解决。中方敦促停止任何针对平民的袭击，呼吁当事方保持冷静克制，严格遵守国际人道法，保护平民和民用基础设施安全，避免伤及第三方平民和民用资产，为早日实现和平争取希望。 …"
